function parseBody(v){
 if(v&&typeof v==="object")return v;
 const s=String(v??"").trim();
 try{return JSON.parse(s)}catch{}
 let last=null;
 for(const line of s.split(/\r?\n/)){
  const t=line.trim();
  if(!t.startsWith("data:"))continue;
  try{last=JSON.parse(t.slice(5).trim())}catch{}
 }
 return last;
}
function normalizePayload(value){
 let current=value;
 for(let depth=0;depth<6;depth++){
  if(typeof current==="string"){
   try{current=JSON.parse(current);continue}catch{return current}
  }
  if(current&&typeof current==="object"){
   if(current.structuredContent!==undefined){current=current.structuredContent;continue}
   if(typeof current.result==="string"){
    try{current=JSON.parse(current.result);continue}catch{}
   }
  }
  return current;
 }
 return current;
}
function parsePayload(message){
 const result=message?.result??{};
 if(result.structuredContent!==undefined)return normalizePayload(result.structuredContent);
 const text=(result.content??[]).filter(x=>x?.type==="text").map(x=>x.text).join("\n");
 return text?normalizePayload(text):normalizePayload(result);
}
const source=$("Build Runtime Test Cases").all().map(x=>x.json);
const items=$input.all();
const parsed=items.map((item,index)=>{
 const json=item.json??{};
 const message=parseBody(json.body??json.data);
 const paired=Array.isArray(item.pairedItem)?item.pairedItem[0]?.item:item.pairedItem?.item;
 return {item,json,message,index,pairedIndex:Number.isInteger(paired)?paired:null};
});
const byId=new Map(),duplicates=new Set();
for(const entry of parsed){
 const id=entry.message?.id;
 if(id===undefined||id===null)continue;
 if(byId.has(id))duplicates.add(id);
 else byId.set(id,entry);
}
const results=[];
for(let i=0;i<source.length;i++){
 const test=source[i],id=test.rpcBody.id;
 let entry=byId.get(id);
 if(!entry)entry=parsed.find(x=>x.pairedIndex===i);
 const item=entry?.json??{},message=entry?.message??null;
 let payload=message?parsePayload(message):null,passed=false,detail="";
 if(duplicates.has(id)){detail="Duplicate JSON-RPC response ID: "+id;}
 else if(!entry){detail="No response could be correlated with JSON-RPC ID "+id+"; inspect transport error and pairedItem metadata.";}
 else if(item.error){detail=String(item.error.message??item.error);}
 else if(Number(item.statusCode??0)>=400){detail="HTTP "+item.statusCode+": "+String(item.body??"").slice(0,400);}
 else if(!message||message.id!==id){detail="Missing response or JSON-RPC ID mismatch.";}
 else if(message.error){detail="JSON-RPC error: "+JSON.stringify(message.error);}
 else if(test.kind==="tools_list"){
  const names=(payload?.tools??[]).map(x=>x.name);
  const required=["analytics_query","get_top_market_skills","get_top_skill_gaps","get_market_skill_details","search_elasticsearch"];
  passed=required.every(x=>names.includes(x));
  detail=passed?"All required MCP tools are registered.":"Missing tools: "+required.filter(x=>!names.includes(x)).join(", ");
 }else if(test.kind==="expected_error"){
  passed=payload?.status==="error"&&!!payload?.error;
  detail=passed?"Invalid dataset returned a structured error envelope ("+(payload.error.code??"error")+").":"Expected structured error; received "+JSON.stringify(payload).slice(0,500);
 }else if(payload?.status==="error"){
  detail="Analytics error: "+JSON.stringify(payload.error).slice(0,500);
 }else if(test.kind==="count"){
  const count=payload?.result?.count;
  passed=payload?.status==="success"&&Number.isInteger(count)&&count>=0;
  detail=passed?"Count returned successfully: "+count:"Count response shape/value invalid: "+JSON.stringify(payload).slice(0,500);
 }else if(test.kind==="select"){
  const rows=payload?.result;
  passed=payload?.status==="success"&&Array.isArray(rows)&&rows.length===1&&rows[0]?.course_id==="C002";
  detail=passed?"Course C002 retrieved.":"Expected exactly one C002 row: "+JSON.stringify(payload).slice(0,500);
 }else if(test.kind==="aggregate"){
  const buckets=payload?.result?.buckets;
  passed=payload?.status==="success"&&Array.isArray(buckets)&&buckets.length>0&&buckets.every(b=>b.group?.skill&&typeof b.metrics?.avg_market_demand==="number"&&typeof b.metrics?.avg_market_gap==="number");
  detail=passed?"Grouped metrics and aliases validated across "+buckets.length+" buckets.":"Aggregate response invalid: "+JSON.stringify(payload).slice(0,700);
 }
 results.push({testId:test.testId,name:test.name,status:passed?"PASS":"FAIL",detail});
}
const passed=results.filter(x=>x.status==="PASS").length,failed=results.length-passed;
return [{json:{suite:"NexusOps MCP Runtime Test Suite",executedAt:new Date().toISOString(),summary:{total:results.length,passed,failed,overall:failed===0?"PASS":"FAIL"},results,instructions:"Results are correlated by JSON-RPC ID; nested MCP structuredContent/result JSON wrappers are normalized before assertions. Inspect failed details for transport or contract evidence."}}];
